/**
 * Bundles data/envs/<id>/* into packages/core/src/sandbox/ingest/prebuilt-files.generated.ts so prebuilt sandbox
 * environments work in serverless functions (no runtime fs reads from the repo root).
 *   npx tsx scripts/gen-sandbox-prebuilt.ts
 * prebuilt.test.ts fails when the generated file drifts from data/envs.
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

const ROOT = resolve(import.meta.dirname, "..");
const IDS = ["acme-support", "tau2-retail"] as const;
const FILES = ["openapi.yaml", "schema.sql", "seed.sql", "policies.md", "workflows.json"] as const;

const entries: string[] = [];
for (const id of IDS) {
  const dir = resolve(ROOT, "data/envs", id);
  if (!FILES.every((f) => existsSync(resolve(dir, f)))) continue;
  const body = FILES.map((f) => `    ${JSON.stringify(f)}: ${JSON.stringify(readFileSync(resolve(dir, f), "utf8"))},`).join("\n");
  entries.push(`  ${JSON.stringify(id)}: {\n${body}\n  },`);
}

const out = `/* eslint-disable */
// GENERATED by scripts/gen-sandbox-prebuilt.ts from data/envs/*. Do not edit by hand.
export const PREBUILT_ENV_FILES: Record<string, Record<"openapi.yaml" | "schema.sql" | "seed.sql" | "policies.md" | "workflows.json", string>> = {
${entries.join("\n")}
};
`;
writeFileSync(resolve(ROOT, "packages/core/src/sandbox/ingest/prebuilt-files.generated.ts"), out);
process.stdout.write(`wrote ${entries.length} prebuilt env(s)\n`);
